    const newKeys = keys - m.price; setKeys(newKeys); try{ localStorage.setItem("loomi_keys", newKeys.toString()); }catch{}
    await updateDoc(doc(db, "loomi_dm_messages", m.id), { unlockedBy: [...(m.unlockedBy||[]), nicknameRef.current] });
